I'm practicing on making bar chart with d3 within Vue3 framework. I have a \<select\> to choose between novels and the bar chart shows the distribution of paragraphs' length of that novel. When I first entering the page, the ticks are all shown. But when I select between the novels, some ticks just disappear at seemingly random pattern. Here's my code:
```
import * as d3 from "d3";

function draw_bar (rect, maxValue) {
  rect.attr("fill", "steelblue")
    .attr("x", function(d, i){
      return 40 + i * 35
    })
    .attr("y", function(d){
      // top of the bar = SVG height 500 - bottom pad 20 - bar height
      return 480 - 460 * (d.counts / maxValue);
    })
    .attr("width", 32)
    .attr("height", function(d){
      // largest bar height = SVG height 500 - bottom & top pad (20+20)
      // every bar height = largest bar height * ratio to the highest bar
      return 460 * (d.counts / maxValue);
    });
}

function draw_axis (yg, maxValue) {
  var yScale = d3.scaleLinear()
    .domain([0, maxValue])
    .rangeRound([460, 0])
    
  console.log(yScale);
  
  var axis = d3.axisLeft(yScale)
  
  console.log(axis);
    
  yg.attr("transform", "translate(40, 20)")
    .call(axis);
}
    
function draw_obj (obj, func, dataset, maxValue) {
  var updateData = d3.select("svg#prac2").selectAll(obj).data(dataset)
  var enterRect = updateData.enter()
  var exitRect = updateData.exit()

  func(updateData, maxValue);
  func(enterRect.append(obj), maxValue);
