}

export function d3draw (dataset) {
  let data_counts = [];
  dataset.forEach( (el) => {data_counts.push(el.counts)} );
  let maxValue = Math.max(...data_counts);
  
  draw_obj("g", draw_axis, [0], maxValue);
  draw_obj("rect", draw_bar, dataset, maxValue);
}
